package com.ruoyi.library.service;
import com.ruoyi.common.exception.ServiceException;import com.ruoyi.library.domain.*;import com.ruoyi.library.dto.VideoPlaybackView;import com.ruoyi.library.mapper.*;import com.ruoyi.library.storage.PrivateFileUrlSigner;import java.time.*;import java.util.Date;import java.util.List;import org.springframework.stereotype.Service;
/** 课程权限判断、私有视频签名和播放进度服务。 */
@Service public class VideoPlaybackService
{private static final Duration URL_TTL=Duration.ofMinutes(10);private final WlCourseMapper courseMapper;private final WlUserCourseMapper grantMapper;private final WlWxUserMapper userMapper;private final WlVideoProgressMapper progressMapper;private final PrivateFileUrlSigner signer;private final Clock clock;public VideoPlaybackService(WlCourseMapper c,WlUserCourseMapper g,WlWxUserMapper u,WlVideoProgressMapper p,PrivateFileUrlSigner s){this(c,g,u,p,s,Clock.systemUTC());}VideoPlaybackService(WlCourseMapper c,WlUserCourseMapper g,WlWxUserMapper u,WlVideoProgressMapper p,PrivateFileUrlSigner s,Clock k){courseMapper=c;grantMapper=g;userMapper=u;progressMapper=p;signer=s;clock=k;}public boolean canPlay(Long userId,Long videoId){WlWxUser u=userMapper.selectById(userId);if(u==null||!"0".equals(u.getStatus()))return false;WlCourseVideo v=courseMapper.selectVideoById(videoId);if(v==null||!"0".equals(v.getStatus()))return false;WlCourse c=courseMapper.selectById(v.getCourseId());if(c==null||!"0".equals(c.getStatus()))return false;if("VIP".equals(c.getAccessType()))return u.getVipExpireTime()!=null&&u.getVipExpireTime().toInstant().isAfter(clock.instant());return "CODE".equals(c.getAccessType())&&grantMapper.selectByUserCourse(userId,c.getId())!=null;}public VideoPlaybackView play(Long userId,Long videoId){if(!canPlay(userId,videoId))throw new ServiceException("当前用户无权播放该课程视频");WlCourseVideo v=courseMapper.selectVideoById(videoId);return new VideoPlaybackView(videoId,signer.signGetUrl(v.getVideoObjectKey(),URL_TTL,null).toString(),URL_TTL.getSeconds());}public void saveProgress(Long userId,Long videoId,int seconds,boolean finished){if(!canPlay(userId,videoId))throw new ServiceException("当前用户无权更新该视频进度");WlCourseVideo v=courseMapper.selectVideoById(videoId);if(seconds<0||v.getDurationSeconds()!=null&&seconds>v.getDurationSeconds())throw new ServiceException("播放进度不正确");WlVideoProgress p=new WlVideoProgress();p.setUserId(userId);p.setCourseId(v.getCourseId());p.setVideoId(videoId);p.setProgressSeconds(seconds);p.setFinished(finished?"1":"0");p.setLastPlayTime(Date.from(clock.instant()));p.setCreateBy(String.valueOf(userId));if(progressMapper.upsertProgress(p)!=1)throw new ServiceException("播放进度保存失败，请重试");}public List<WlVideoProgress> listProgress(Long userId){return progressMapper.selectByUser(userId);}}
